const r = wb.getRange('Sheet1!E4:E12');
const fs = [];
for (let i = 4; i <= 12; i++) fs.push([`=INDEX($B$4:$B$15,AGGREGATE(15,6,(ROW($B$4:$B$15)-ROW($B$4)+1)/(LEFT($B$4:$B$15,2)="PK"),ROWS(E$4:E${i})))`]);
r.setValues(fs);
const out = [];
for (let i = 4; i <= 12; i++) { const c = wb.getRange('Sheet1!E'+i); out.push(['E'+i, JSON.stringify(c.getValue()), c.getFormula ? c.getFormula() : '']); }
log(JSON.stringify(out, null, 0));
log('PK count', await wb.evaluate('=COUNTIF(Sheet1!B4:B15,"PK*")'));
log('match count', await wb.evaluate('=SUMPRODUCT(--(Sheet1!E4:E12=FILTER(Sheet1!B4:B15,LEFT(Sheet1!B4:B15,2)="PK")))'));
log('B len vs E len', await wb.evaluate('=SUMPRODUCT(LEN(Sheet1!B6:B8))+SUMPRODUCT(LEN(Sheet1!B10:B15))-SUMPRODUCT(LEN(Sheet1!E4:E12))'));
wb.getRange('Sheet1!E3:E13')

